import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, texture, vec3, mix, uniform, varying } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create the root group
  const group = new THREE.Group();
  group.userData.handlers = {};
  group.userData.cleanup = cleanup;

  const timelines = [];
  const resources = { textures: [], cleanup: [] };

  // Load textures asynchronously
  Promise.all([
    config.imageUrl ? ctx.textureLoader.loadTexture(config.imageUrl) : null,
    config.depthMapUrl ? ctx.textureLoader.loadTexture(config.depthMapUrl) : null
  ]).then(([colorTex, depthTex]) => {
    if (!colorTex) return;

    // Store for cleanup
    if (colorTex) resources.textures.push(colorTex);
    if (depthTex) resources.textures.push(depthTex);

    // Create tessellated plane geometry with displacement
    const geometry = new THREE.PlaneGeometry(2, 1.25, 64, 64);

    // Build TSL material with displacement
    const colorMap = uniform(colorTex);
    const displacementMap = depthTex ? uniform(depthTex) : null;

    // Displacement strength (subtle parallax effect)
    const displacementScale = uniform(0.08);

    // Create varying for parallax based on vertex position
    const vUv = varying(uv());

    // Displacement node: sample depth, apply to position
    let positionNode = vUv;
    if (displacementMap) {
      const depth = texture(displacementMap, vUv);
      // Apply subtle displacement to vertex positions
      positionNode = mix(
        vec3(vUv.x, vUv.y, 0),
        vec3(vUv.x, vUv.y, depth.r.mul(displacementScale)),
        0.5
      );
    }

    // Color sampling from texture
    const colorSample = texture(colorMap, vUv);

    const material = new MeshBasicNodeMaterial({
      colorNode: colorSample,
      side: THREE.FrontSide,
      transparent: true
    });

    const mesh = new THREE.Mesh(geometry, material);
    mesh.scale.set(1, 1, 1);
    group.add(mesh);

    // Store mesh for interaction handlers
    group.userData.mesh = mesh;
    group.userData.material = material;
    group.userData.geometry = geometry;
  }).catch(err => {
    console.warn('Texture load failed for parallax-plane:', err);
  });

  // Hover interaction: subtle rise-in effect (0.15 units)
  const raycaster = new THREE.Raycaster();
  const mouse = new THREE.Vector2();

  group.userData.handlers.hover = (event) => {
    if (!group.userData.mesh) return;

    // On hover enter: rise-in animation
    const hoverTimeline = gsap.timeline();
    timelines.push(hoverTimeline);

    hoverTimeline.to(group.position, {
      y: group.position.y + 0.15,
      duration: 0.5,
      ease: 'power2.out'
    }, 0);

    // Subtle rotation tilt on hover (max 3 degrees)
    hoverTimeline.to(group.rotation, {
      z: 0.05,
      duration: 0.3,
      ease: 'power2.out'
    }, 0);
  };

  group.userData.handlers.hoverOut = (event) => {
    if (!group.userData.mesh) return;

    // Reset position and rotation
    const resetTimeline = gsap.timeline();
    timelines.push(resetTimeline);

    // Apply weighted settle motion (overshoot then settle)
    resetTimeline.to(group.position, {
      y: config.scenePosition?.[1] ?? 1.6,
      duration: 0.7,
      ease: 'back.out',
      overwrite: 'auto'
    }, 0);

    resetTimeline.to(group.rotation, {
      z: 0,
      duration: 0.5,
      ease: 'power2.out',
      overwrite: 'auto'
    }, 0);
  };

  group.userData.handlers.click = (event) => {
    if (!group.userData.mesh) return;

    // Press-down effect: scale 0.97 in 120ms
    const pressTimeline = gsap.timeline();
    timelines.push(pressTimeline);

    pressTimeline.to(group.scale, {
      x: 0.97,
      y: 0.97,
      duration: 0.12,
      ease: 'back.out'
    }, 0);

    pressTimeline.to(group.scale, {
      x: 1,
      y: 1,
      duration: 0.3,
      ease: 'back.out'
    }, 0.12);

    // Emit navigation event
    ctx.emit('hub-features.select', { type: 'feature-row-click' });

    // Handle checkout navigation if data binding present
    if (config.dataBindings && config.dataBindings.length > 0) {
      const checkoutBinding = config.dataBindings.find(
        b => b.source === 'trpc.checkout.begin.checkoutUrl'
      );
      if (checkoutBinding && checkoutBinding.target === 'onClick.navigate') {
        // In real scenario, would fetch from tRPC and navigate
        // For now, emit a navigation event
        ctx.emit('navigate', { intent: 'checkout' });
      }
    }
  };

  function cleanup() {
    // Kill all GSAP timelines
    timelines.forEach(tl => tl.kill());

    // Dispose textures
    resources.textures.forEach(tex => tex.dispose?.());

    // Dispose geometry and material if created
    if (group.userData.geometry) group.userData.geometry.dispose();
    if (group.userData.material) group.userData.material.dispose?.();

    // Clear handlers
    group.userData.handlers = {};
  }

  return group;
}
